/-- All measurable scalar estimators using the first sample and a known reference vector. -/
abbrev KnownL1Estimator (n k : ℕ) :=
  {f : (Fin n → Fin k) → ℝ // Measurable f}

/-- Causal laws in the stated model class. -/
abbrev ModelLaw (d : ℕ) (epsilon : ℝ) :=
  {Q : PotentialLaw d // CausalModelClass epsilon Q}

/-- Contrasts on the stated cube. -/
def PairedContrasts (k : ℕ) :=
  {theta : Fin k → ℝ // ∀ i, theta i ∈ Set.Icc (-1 / 8) (1 / 8)}

/-- Measurable scalar estimators of the half-budget value. -/
abbrev ScalarEstimator (n d : ℕ) :=
  {f : (Fin n → Obs d) → ℝ // Measurable f}

/-- For [d](hyp:d), [Q](hyp:Q), [b](hyp:b), the budget policy class definition specifies [the stated object](goal). -/
def budgetPolicyClass {d : ℕ} (Q : PotentialLaw d)
    (b : Set.Icc (0 : ℝ) 1) : Set (Fin d → ℝ) :=
  {pi | (∀ j, pi j ∈ Set.Icc (0 : ℝ) 1) ∧ ∑ j, poCellMass Q j * pi j ≤ b.1}

/-- The hard capacity-active subclass, including the binding requirement. -/
def capacityHardClass (d : ℕ) (epsilon : ℝ) : Set (PotentialLaw d) :=
  {Q | CausalModelClass epsilon Q ∧ budgetValue Q 1 = 1 / 2 ∧
    (∀ j, 0 < poCellMass Q j → effect Q j ∈ Set.Icc (1 / 8 : ℝ) (3 / 8)) ∧
    BindingHalfBudget Q}

