          ∀ (P : CausalSmith.Stat.DiscreteBudgetvalueCurve.DiscreteLaw d) (counts : (Fin d → CausalSmith.Stat.DiscreteBudgetvalueCurve.Cell → ℕ) × (Fin d → CausalSmith.Stat.DiscreteBudgetvalueCurve.Cell → ℕ)) (j : Fin d),
            CausalSmith.Stat.DiscreteBudgetvalueCurve.idealPilotGood P counts j →
              have m := ↑n / 8;
              have center := CausalSmith.Stat.DiscreteBudgetvalueCurve.pilotMidpoint m d (counts.1 j);
              have radius := CausalSmith.Stat.DiscreteBudgetvalueCurve.pilotRadius m d (counts.1 j);
              have q := CausalSmith.Stat.DiscreteBudgetvalueCurve.cellVector P j;
              |CausalSmith.Stat.DiscreteBudgetvalueCurve.thresholdFunReal epsilon lambda center + (MvPolynomial.eval (Causalean.Mathlib.Analysis.JacksonApproximation.normalizedPoint (fun i => center (CausalSmith.Stat.DiscreteBudgetvalueCurve.CellFourEquiv.symm i)) (fun i => radius (CausalSmith.Stat.DiscreteBudgetvalueCurve.CellFourEquiv.symm i)) fun i => q (CausalSmith.Stat.DiscreteBudgetvalueCurve.CellFourEquiv.symm i))) (CausalSmith.Stat.DiscreteBudgetvalueCurve.localJacksonPolynomial epsilon lambda (CausalSmith.Stat.DiscreteBudgetvalueCurve.jacksonDegree d) center radius) - CausalSmith.Stat.DiscreteBudgetvalueCurve.thresholdFunReal epsilon lambda q| ≤
